// ObjectView's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/object_view.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// Icons or details. An undeclared mode throws std::invalid_argument; a change keeps the first visible item in view and ends a header interaction. A view, so the write can keep the first visible item.
template <typename Declaring>
struct ObjectViewViewModeCapability {
    PropertyView<ObjectViewMode, ObjectViewViewModeCapability<Declaring>> view_mode;

    static void assign(ObjectViewViewModeCapability& capability, ObjectViewMode incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.view_mode), std::move(incoming));
    }

    static ObjectViewMode read(const ObjectViewViewModeCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        ObjectViewMode current = control.read_view(capability.view_mode);
        return current;
    }
};

// The primary selected item's stable ID, or empty; a view over the selection (G2). A write selects that item alone, or clears the selection, and raises selection_changed; an ID not in the model throws std::out_of_range. set_selected_ids sets several.
template <typename Declaring>
struct ObjectViewSelectedIdCapability {
    PropertyView<std::string, ObjectViewSelectedIdCapability<Declaring>> selected_id;

    static void assign(ObjectViewSelectedIdCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.selected_id), std::move(incoming));
    }

    static std::string read(const ObjectViewSelectedIdCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::string current = control.read_view(capability.selected_id);
        return current;
    }
};

// Whether one item or several may be selected. Turning on single selection keeps only the primary item.
template <typename Declaring>
struct ObjectViewSelectionModeCapability {
    PropertyCell<ObjectSelectionMode, ObjectViewSelectionModeCapability<Declaring>> selection_mode{ObjectSelectionMode::multiple};

    static void assign(ObjectViewSelectionModeCapability& capability, ObjectSelectionMode incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.selection_mode), incoming);
        if (!capability.selection_mode.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.selection_mode));
    }
};

// The icon mode's cell size, 86 by 78 through 512 by 512 (std::invalid_argument otherwise).
template <typename Declaring>
struct ObjectViewIconCellSizeCapability {
    PropertyCell<Size, ObjectViewIconCellSizeCapability<Declaring>> icon_cell_size{Size{112.0, 91.0}};

    static void assign(ObjectViewIconCellSizeCapability& capability, Size incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.icon_cell_size), incoming);
        if (!capability.icon_cell_size.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.icon_cell_size));
    }
};

